import os

def create_app(storage_dir):
    # Initialize Flask app
    app = Flask(__name__)

    # Define a route for downloading files
    @app.route('/download', methods=['GET'])
    def download_file():
        # Get the file name from the query parameter
        file_name = request.args.get('file')

        # Check if the file exists in the storage directory
        if file_name and os.path.isfile(os.path.join(storage_dir, file_name)):
            # Serve the file as a binary response
            return send_from_directory(storage_dir, file_name, as_attachment=True)
        else:
            # Return an error message if the file does not exist
