from operator import add, sub, mul, truediv, floordiv, mod, eq, ne, lt, le, gt, ge

def parse_list(text):
    # Use ast.literal_eval to parse literal values
    try:
        return ast.literal_eval(text)
    except ValueError:
        # If it's not a literal, parse as an expression
        tree = ast.parse(text, mode='eval')
        return evaluate_tree(tree, {})

def evaluate_tree(node, env):
    # Base case: if it's a constant number or string, return it
    if isinstance(node, ast.Constant):
        return node.value
    # Base case: if it's a name, return its value from the environment
    elif isinstance(node, ast.Name):
        return env.get(node.id, node.id)
    # If it's a binary operation, evaluate left and right subtrees
    elif isinstance(node, ast.BinOp):
        left = evaluate_tree(node.left, env)
        right = evaluate_tree(node.right, env)
        op = getattr(operator, node.op.__name__)
        return op(left, right)
    # If it's a unary operation, evaluate the subtree
    elif isinstance(node, ast.UnaryOp):
        operand = evaluate_tree(node.operand, env)
        op = getattr(operator, node.op.__name__)
        return op(operand)
    # If it's a comparison, evaluate left and right subtrees
    elif isinstance(node, ast.Compare):
        left = evaluate_tree(node.left, env)
        right = evaluate_tree(node.right, env)
        for op, value in zip(node.ops, node.comparators):
            op_func = getattr(operator, op.__name__)
            if not op_func(left, value):
                return False
        return True
    # If it's a boolean operation, evaluate left and right subtrees
    elif isinstance(node, ast.BoolOp):
        left = evaluate_tree(node.left, env)
        right = evaluate_tree(node.right, env)
        if node.op.__name__ == 'and':
            return left and right
        else:
            return left or right
    # If it's any other node, raise ValueError
    else:
        raise ValueError(f"Unsupported node type: {node}")

