import ast
import operator

def parse_dict_literal(s):
    allowed = {}
    if s.startswith('{') and s.endswith('}'):
        # Parse the dictionary using the ast.literal_eval function
        return ast.literal_eval(s)

    # Construct a dictionary parser
    class DictParser(ast.NodeVisitor):
        def __init__(self, allowed):
            self.allowed = allowed
            self.result = {}

        def visit_Name(self, node):
            # Check if the name is allowed
            if node.id in self.allowed:
                return self.allowed[node.id]
            else:
                raise ValueError(f'Name {node.id} not allowed')

        def visit_Constant(self, node):
            # Return the constant value
            return node.value

        def visit_BinOp(self, node):
            # Perform the binary operation
            left = self.visit(node.left)
            right = self.visit(node.right)
            return operator.eq(left, right) if node.op == operator.Eq else operator.ne(left, right)

        def visit_UnaryOp(self, node):
            # Perform the unary operation
            op = operator.attrgetter('op')(node.op)
            value = self.visit(node.operand)
            return operator.neg(value) if op == operator.Neg else operator.pos(value)

        def visit_Compare(self, node):
            # Perform the comparison
            left = self.visit(node.left)
            right = self.visit(node.right)
            if node.op == operator.Eq:
                return left == right
            elif node.op == operator.NotEq:
                return left != right
            elif node.op == operator.Lt:
                return left < right
            elif node.op == operator.LtE:
                return left <= right
            elif node.op == operator.Gt:
                return left > right
            elif node.op == operator.GtE:
                return left >= right
            else:
                raise ValueError(f'Unsupported comparison operator {node.op}')

        def visit_BoolOp(self, node):
            # Perform the boolean operation
            op = operator.attrgetter('op')(node.op)
            left = self.visit(node.left)
            right = self.visit(node.right)
            if op == operator.And:
                return left and right
            elif op == operator.Or:
                return left or right
            else:
                raise ValueError(f'Unsupported boolean operator {node.op}')

    # Parse the string using the DictParser
    parser = DictParser(allowed)
    ast.parse(s, mode='eval').visit(parser)

    # Return the parsed dictionary
    return parser.result
